package io.github.dominys.cujex.examples.api.model;

import lombok.Builder;
import lombok.extern.jackson.Jacksonized;

import java.time.Instant;
import java.util.List;

/**
 * An order in the sample Order service.
 *
 * <p>Immutable record whose builder is generated by Lombok. See {@link Customer}
 * for why the builder exists (Jackson deserialization + field-level editing by
 * the infra) and how {@link Builder @Builder}/{@link Jacksonized @Jacksonized}
 * provide it.
 *
 * <p>Fields exercised by the example scenarios:
 * <ul>
 *     <li>{@code id} - assigned by the service on create; referenced later as
 *         {@code ${created.id()}}.</li>
 *     <li>{@code customer} - a reference to another stored entity, injected into
 *         the table cell via {@code ${customer1}}.</li>
 *     <li>{@code tags} - a list, built from a JEXL literal array
 *         {@code ${[`vip`,`priority`]}}.</li>
 *     <li>{@code items} - a list of structured {@link OrderItem} line items, which
 *         can be built from a JSON stub's nested array or indexed in JEXL as
 *         {@code ${created.items().get(0).sku()}}.</li>
 *     <li>{@code createdAt} - an {@link Instant}, often built from the custom
 *         JEXL function {@code ${now('-PT1H')}}.</li>
 * </ul>
 */
@Jacksonized
@Builder(toBuilder = true)
public record Order(String id,
                    double price,
                    OrderStatus status,
                    List<String> tags,
                    List<OrderItem> items,
                    Instant createdAt,
                    Customer customer) {
}
